{
  "verdict": "request_changes",
  "summary": "Candidate does not preserve the original relative order of tickets with equal priority.",
  "findings": [
    {
      "finding_id": "F1",
      "file": "candidate.py",
      "line_start": 2,
      "line_end": 2,
      "severity": "high",
      "description": "Reversing the sorted list after sorting by priority breaks the required stability for equal priorities. The implementation returns tickets in reverse order for tickets sharing the same priority, violating the contract that equal priority tickets keep their original relative order.",
      "evidence": "Example: tickets = [(\"t1\", 5), (\"t2\", 5), (\"t3\", 4)] \nCandidate output: ['t2', 't1', 't3'] \nExpected output: ['t1', 't2', 't3']"
    }
  ]
}
